/* PRIME Ledger frontend — single API client, cache, guarded rendering and responsive UI. */
(() => {
  'use strict';
  const cfg = window.PRIME_CONFIG || {};
  const state = { page:'dashboard', periods:[], kpi:[], dashboard:null, rbb:null, renbis:[], xray:[], movers:null, trends:null, costs:null, manual:[], database:[], targets:{}, charts:{}, cache:new Map(), pending:new Map(), selectedImport:null, actions:[], hierarchy:null, reportType:'executive', lastUpdated:null, navRequest:0, notifications:[], recentPages:[], searchItems:[], searchIndex:0, dashboardMode:'executive', tableSort:{}, tablePagination:{} };
  const $ = (id) => document.getElementById(id);
  let eventsBound = false;
  const AUTH_TOKEN_KEY = 'prime_ledger_session_token';
  const AUTH_USER_KEY = 'prime_ledger_session_user';
  const sessionToken = () => { try { return sessionStorage.getItem(AUTH_TOKEN_KEY) || ''; } catch (_) { return ''; } }
  const saveSession = (token, username) => { try { sessionStorage.setItem(AUTH_TOKEN_KEY, token); sessionStorage.setItem(AUTH_USER_KEY, username || 'admin'); } catch (_) {} }
  const clearSession = () => { try { sessionStorage.removeItem(AUTH_TOKEN_KEY); sessionStorage.removeItem(AUTH_USER_KEY); } catch (_) {} }
  function showLogin(message='') { document.body.classList.remove('authenticated'); $('loginScreen').hidden=false; $('loginError').textContent=message; $('loginError').hidden=!message; $('loginSubmit').disabled=false; $('loginSubmit').innerHTML='<i class="fa-solid fa-right-to-bracket"></i> Masuk'; }
  function showApp() { document.body.classList.add('authenticated'); $('loginScreen').hidden=true; }
  const money = (v, digits=0) => Number.isFinite(Number(v)) ? new Intl.NumberFormat('id-ID',{maximumFractionDigits:digits,minimumFractionDigits:digits}).format(Number(v)) : '—';
  const idr = (v, digits=2) => v !== null && v !== undefined && v !== '' && Number.isFinite(Number(v)) ? `Rp\u00a0${new Intl.NumberFormat('id-ID',{minimumFractionDigits:digits,maximumFractionDigits:digits}).format(Number(v))}` : '—';
  const moneyCompact = (v) => { const n=Number(v); if(!Number.isFinite(n)) return '—'; const a=Math.abs(n); if(a>=1e12)return `Rp ${(n/1e12).toLocaleString('id-ID',{maximumFractionDigits:2})} triliun`; if(a>=1e9)return `Rp ${(n/1e9).toLocaleString('id-ID',{maximumFractionDigits:2})} miliar`; if(a>=1e6)return `Rp ${(n/1e6).toLocaleString('id-ID',{maximumFractionDigits:2})} juta`; return idr(n,0); };
  const pct = (v) => v === null || v === undefined || v === '' || !Number.isFinite(Number(v)) ? '—' : `${Number(v).toLocaleString('id-ID',{maximumFractionDigits:2})}%`;
  const escapeHTML = (v) => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const period = () => $('periodSelector')?.value || '';
  const comparePeriod = () => $('compareSelector')?.value || '';
  const cacheKey = (action, params) => `${action}:${JSON.stringify(params||{})}`;
  function safeStorageGet(key){try{return window.localStorage.getItem(key)}catch(_){return null}}
  function safeStorageSet(key,value){try{window.localStorage.setItem(key,value)}catch(_){/* Storage may be disabled by browser privacy policy. */}}

  function toast(message, type='info', timeout=4600) {
    const region=$('toastRegion'); if(!region)return;
    const kinds={success:{icon:'fa-circle-check',label:'Berhasil'},error:{icon:'fa-circle-exclamation',label:'Perlu perhatian'},warning:{icon:'fa-triangle-exclamation',label:'Peringatan'},info:{icon:'fa-circle-info',label:'Informasi'}};
    const kind=kinds[type]||kinds.info, node=document.createElement('div'); node.className=`toast toast-${type}`; node.setAttribute('role',type==='error'?'alert':'status');
    const icon=document.createElement('span');icon.className='toast-icon';icon.innerHTML=`<i class="fa-solid ${kind.icon}"></i>`;
    const body=document.createElement('div');body.className='toast-body';const title=document.createElement('strong');title.textContent=kind.label;const msg=document.createElement('span');msg.textContent=String(message||'Terjadi kesalahan');body.append(title,msg);
    const close=document.createElement('button');close.type='button';close.className='toast-close';close.setAttribute('aria-label','Tutup notifikasi');close.innerHTML='<i class="fa-solid fa-xmark"></i>';
    const progress=document.createElement('span');progress.className='toast-progress';progress.style.animationDuration=`${timeout}ms`;node.append(icon,body,close,progress);region.appendChild(node);
    recordNotification(kind.label, String(message||'Terjadi kesalahan'), type);
    const dismiss=()=>{if(node.classList.contains('toast-leaving'))return;node.classList.add('toast-leaving');setTimeout(()=>node.remove(),220);};
    close.addEventListener('click',()=>{clearTimeout(timer);dismiss();});const timer=setTimeout(dismiss,timeout);
  }
  function setConnection(status, label) { $('connectionDot').className=`status-dot ${status}`; $('connectionLabel').textContent=label; }
  function loader(show, text='Memuat data…') { $('loaderText').textContent=text; $('globalLoader').hidden=!show; }
  function updateStamp() { state.lastUpdated=new Date(); $('lastUpdated').textContent=`Pembaruan terakhir: ${state.lastUpdated.toLocaleString('id-ID')}`; }
  function apiError(message) { setConnection(navigator.onLine?'online':'offline',navigator.onLine?'Backend belum terverifikasi':'Offline'); toast(message,'error',6500); }

  async function api(action, params={}, method='GET', options={}) {
    if (!cfg.API_URL || !/^https:\/\//i.test(cfg.API_URL)) throw new Error('API_URL belum dikonfigurasi pada config.js.');
    const key=cacheKey(action,{...params,method,session:action==='login'?'login':(sessionToken()?'authenticated':'anonymous')}); const ttl=options.ttl ?? cfg.CACHE_TTL_MS ?? 60000;
    if(method==='GET' && !options.force) { const c=state.cache.get(key); if(c && Date.now()-c.time<ttl) return c.data; if(state.pending.has(key)) return state.pending.get(key); }
    const task=(async()=>{
      let url=new URL(cfg.API_URL); const init={method:'GET',redirect:'follow',cache:'no-store'};
      if(method==='GET') { url.searchParams.set('action',action); Object.entries(params||{}).forEach(([k,v])=>{if(v!==undefined&&v!==null)url.searchParams.set(k,String(v));}); if(action!=='login' && sessionToken())url.searchParams.set('token',sessionToken()); }
      else { init.method='POST'; init.headers={'Content-Type':'text/plain;charset=utf-8'}; init.body=JSON.stringify({action,...params,...(action==='login'?{}:{token:sessionToken()})}); }
      const controller=new AbortController(); init.signal=controller.signal;
      const timer=setTimeout(()=>controller.abort(),options.timeout||30000);
      let response, raw, result;
      try { response=await fetch(url,init); raw=await response.text(); } catch(e) { if(e.name==='AbortError') throw new Error('Permintaan ke backend melewati batas waktu.'); throw new Error('Tidak dapat menghubungi backend. Periksa URL deployment, izin akses, dan konfigurasi CORS Google Apps Script.'); } finally { clearTimeout(timer); }
      if(!response.ok) throw new Error(`Backend merespons HTTP ${response.status}.`);
      if(!raw || raw.trim().startsWith('<')) throw new Error('Backend mengembalikan halaman HTML, bukan JSON. Periksa deployment dan autentikasi Google Apps Script.');
      try { result=JSON.parse(raw); } catch { throw new Error('Respons backend bukan JSON yang valid.'); }
      if(result.status==='error') throw new Error(result.message||'Operasi backend gagal.');
      const data=Object.prototype.hasOwnProperty.call(result,'data')?result.data:result;
      if(method==='GET') state.cache.set(key,{data,time:Date.now()});
      setConnection('online','Backend terhubung'); return data;
    })();
    if(method==='GET') state.pending.set(key,task);
    try { return await task; } finally { if(state.pending.get(key)===task)state.pending.delete(key); }
  }
  function invalidateCache(prefix='') { if(!prefix){state.cache.clear();return;} for(const k of state.cache.keys())if(k.startsWith(prefix))state.cache.delete(k); }
  async function mutate(action, params={}) { if(cfg.ENABLE_MUTATIONS===false)throw new Error('Operasi perubahan data dinonaktifkan melalui config.js.'); const result=await api(action,params,'POST',{timeout:60000}); invalidateCache(); updateStamp(); return result; }

  function currentPageTitle(id){return ({dashboard:'Executive Board',rbb:'RBB Tracker',audit:'Financial Audit',trends:'Market Volatility',health:'Health Check & Simulasi',cost:'Cost Control',reports:'Reporting Hub',database:'Database & Import',manual:'Input Manual',targets:'Target RENBIS'})[id]||'PRIME Ledger';}
  function showPage(id) {
    if(!$(`page-${id}`))return; state.page=id; state.navRequest++; recordRecentPage(id);
    document.querySelectorAll('.page').forEach(p=>p.classList.toggle('active',p.id===`page-${id}`));
    document.querySelectorAll('.nav-item, .mobile-bottom-nav button').forEach(b=>{const active=b.dataset.page===id;b.classList.toggle('active',active);if(b.classList.contains('nav-item'))b.setAttribute('aria-current',active?'page':'false');}); $('pageTitle').textContent=currentPageTitle(id); document.body.classList.remove('nav-open'); $('menuToggle')?.setAttribute('aria-expanded','false'); window.scrollTo({top:0,behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});
    if(id==='dashboard')loadDashboard(); else if(id==='rbb')loadRBB(); else if(id==='audit')loadAudit(); else if(id==='trends')loadTrends(); else if(id==='health')loadHealth(); else if(id==='cost')loadCost(); else if(id==='database')loadDatabase(); else if(id==='manual')loadManual(); else if(id==='targets')loadTargets(); else if(id==='reports' && !$('reportPreview').dataset.ready)buildReport('executive');
  }
  async function init() {
    $('appVersion').textContent=`v${cfg.APP_VERSION||'1.0.0'}`; initTheme(); loadWorkspaceState(); renderNotificationCenter(); if(!eventsBound){bindEvents();window.addEventListener('online',()=>setConnection('online','Internet tersedia'));window.addEventListener('offline',()=>setConnection('offline','Tidak ada internet'));eventsBound=true;}
    if(!navigator.onLine)setConnection('offline','Tidak ada internet');
    loader(true,'Menghubungkan ke PRIME Ledger…');
    try { const periods=await api('getPeriodList',{},'GET',{force:true,ttl:0,timeout:20000}); state.periods=Array.isArray(periods)?periods:[]; fillPeriodSelectors(); setConnection('online','Backend terhubung'); $('dataNotice').querySelector('span').textContent=state.periods.length?`Tersedia ${state.periods.length} periode. Rekonsiliasi angka dengan laporan resmi sebelum digunakan.`:'Backend terhubung, tetapi belum ada periode neraca. Impor data melalui menu Database & Import.'; showPage('dashboard'); }
    catch(e){ if(/sesi tidak valid|kedaluwarsa|silakan login kembali/i.test(e.message||'')){clearSession();showLogin('Sesi login telah berakhir. Silakan masuk kembali.');return;} setConnection(navigator.onLine?'offline':'offline','Backend belum terhubung'); $('dataNotice').querySelector('span').textContent='Belum dapat membaca backend. Periksa API_URL, deployment Apps Script, otorisasi, dan izin CORS. Jangan gunakan angka lama sebagai angka terkini.'; showErrorPanel(e.message); }
    finally{loader(false);}
  }
  function bindEvents(){
    document.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>showPage(b.dataset.page)));
    $('menuToggle').addEventListener('click',()=>{const open=document.body.classList.toggle('nav-open');$('menuToggle').setAttribute('aria-expanded',String(open));}); $('mobileBackdrop').addEventListener('click',()=>{document.body.classList.remove('nav-open');$('menuToggle').setAttribute('aria-expanded','false');});
    $('themeToggle').addEventListener('click',toggleTheme); $('refreshBtn').addEventListener('click',()=>refreshCurrent(true));
    $('globalSearchBtn').addEventListener('click',openCommandPalette); $('dashboardModeToggle').addEventListener('click',toggleDashboardMode);
    ['auditTable','costTable','moversTable'].forEach(id=>{const table=$(id);table?.querySelector('thead')?.addEventListener('click',e=>{const th=e.target.closest('th');if(th)sortTableByHeader(table,th);});}); $('notificationBtn').addEventListener('click',openNotificationCenter); $('workspaceBtn').addEventListener('click',openWorkspace); $('globalSearchInput').addEventListener('input',renderGlobalSearch); $('globalSearchInput').addEventListener('keydown',handleGlobalSearchKeys); $('saveCurrentView').addEventListener('click',saveCurrentView); $('clearNotifications').addEventListener('click',clearNotifications); $('openAuditFromInsight').addEventListener('click',()=>showPage('audit'));
    document.querySelectorAll('[data-close-dialog]').forEach(b=>b.addEventListener('click',()=>$(b.dataset.closeDialog)?.close()));
    document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openCommandPalette();} if(e.key==='Escape'){document.body.classList.remove('nav-open');$('menuToggle')?.setAttribute('aria-expanded','false');}});
    $('kpiGrid').addEventListener('click',e=>{const fav=e.target.closest('[data-favorite-kpi]');if(fav){e.stopPropagation();toggleFavoriteKpi(fav.dataset.favoriteKpi);return;}});
    $('periodSelector').addEventListener('change',()=>{invalidateCache();refreshCurrent(true);}); $('compareSelector').addEventListener('change',()=>{invalidateCache();refreshCurrent(true);}); $('kpiGrid').addEventListener('click',e=>{if(e.target.closest('[data-favorite-kpi]'))return;const card=e.target.closest('[data-kpi-label]');if(card)openKpiDetail(card.dataset.kpiLabel);}); $('kpiGrid').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){const card=e.target.closest('[data-kpi-label]');if(card){e.preventDefault();openKpiDetail(card.dataset.kpiLabel);}}});
    $('dismissNotice').addEventListener('click',()=>$('dataNotice').hidden=true);
    $('rbbSearch').addEventListener('input',filterRBB); $('auditSearch').addEventListener('input',renderAudit); $('auditDirection').addEventListener('change',renderAudit); $('auditMateriality').addEventListener('change',renderAudit); $('costSearch').addEventListener('input',renderCosts);
    document.querySelectorAll('[data-export-table]').forEach(b=>b.addEventListener('click',()=>exportTable(b.dataset.exportTable)));
    document.querySelectorAll('[data-report]').forEach(b=>b.addEventListener('click',()=>buildReport(b.dataset.report)));
    $('exportExecutive').addEventListener('click',()=>{buildReport('executive');setTimeout(()=>window.print(),150)}); $('printReport').addEventListener('click',()=>window.print()); $('downloadReportCsv').addEventListener('click',downloadReportCsv);
    $('runSimulation').addEventListener('click',runSimulation); $('fileUpload').addEventListener('change',e=>readImportFile(e.target.files?.[0]));
    $('uploadZone').addEventListener('dragover',e=>{e.preventDefault();$('uploadZone').classList.add('dragging')}); $('uploadZone').addEventListener('dragleave',()=>$('uploadZone').classList.remove('dragging')); $('uploadZone').addEventListener('drop',e=>{e.preventDefault();$('uploadZone').classList.remove('dragging');readImportFile(e.dataTransfer.files?.[0])});
    $('confirmImport').addEventListener('click',confirmImport); $('cancelImport').addEventListener('click',cancelImport); $('reloadDatabase').addEventListener('click',loadDatabase); $('manualForm').addEventListener('submit',saveManual); $('reloadManual').addEventListener('click',loadManual); $('loadTargets').addEventListener('click',loadTargets); $('saveTargets').addEventListener('click',saveTargets); $('actionForm').addEventListener('submit',saveAction);
  }
  function fillPeriodSelectors(){const p=$('periodSelector'),c=$('compareSelector'),m=$('manualPeriod'); p.replaceChildren();c.replaceChildren();m.replaceChildren(); if(!state.periods.length){p.add(new Option('Belum ada data',''));c.add(new Option('—',''));} else {state.periods.forEach((x,i)=>{p.add(new Option(x,x));c.add(new Option(x,x));m.add(new Option(x,x));if(i===1)c.value=x;});} }
  function initTheme(){const saved=safeStorageGet('prime_theme');document.body.dataset.theme=['light','dark','contrast'].includes(saved)?saved:'dark';state.dashboardMode=safeStorageGet('prime_dashboard_mode')==='analyst'?'analyst':'executive';updateThemeIcon();updateDashboardModeButton();}
  function toggleTheme(){const modes=['dark','light','contrast'],current=document.body.dataset.theme||'dark',next=modes[(modes.indexOf(current)+1)%modes.length];document.body.dataset.theme=next;safeStorageSet('prime_theme',next);updateThemeIcon();Object.values(state.charts).forEach(ch=>{if(ch){ch.options.plugins.legend.labels.color=getCss('--muted');ch.options.scales?.x?.ticks&&(ch.options.scales.x.ticks.color=getCss('--muted'));ch.options.scales?.y?.ticks&&(ch.options.scales.y.ticks.color=getCss('--muted'));ch.update('none');}});toast(`Tema ${next==='contrast'?'High Contrast':next==='light'?'Executive Light':'Executive Dark'} diaktifkan.`,'info',2500);}
  function updateThemeIcon(){const mode=document.body.dataset.theme;$('themeToggle').innerHTML=mode==='dark'?'<i class="fa-solid fa-sun"></i>':mode==='light'?'<i class="fa-solid fa-circle-half-stroke"></i>':'<i class="fa-solid fa-eye"></i>';const label=mode==='dark'?'Ganti ke tema terang':mode==='light'?'Ganti ke tema kontras tinggi':'Ganti ke tema gelap';$('themeToggle').title=label;$('themeToggle').setAttribute('aria-label',label);}
  function getCss(v){return getComputedStyle(document.body).getPropertyValue(v).trim();}
  function showErrorPanel(msg){const node=$('kpiGrid');node.innerHTML=`<div class="panel" style="grid-column:1/-1"><h3>Data belum tersedia</h3><p class="muted">${escapeHTML(msg)}</p><button class="btn btn-primary" id="retryConnect">Coba lagi</button></div>`; $('retryConnect')?.addEventListener('click',init);}
  async function refreshCurrent(force=false){if(force)invalidateCache();try{if(state.page==='dashboard')await loadDashboard(force);else if(state.page==='rbb')await loadRBB(force);else if(state.page==='audit')await loadAudit(force);else if(state.page==='trends')await loadTrends(force);else if(state.page==='health')await loadHealth(force);else if(state.page==='cost')await loadCost(force);else if(state.page==='database')await loadDatabase(force);else if(state.page==='manual')await loadManual(force);else if(state.page==='targets')await loadTargets(force);else if(state.page==='reports')await buildReport(state.reportType,force);}catch(e){apiError(e.message)}}
  async function withPageLoading(fn){const id=state.page;try{await fn();updateStamp();}catch(e){apiError(e.message)} }
  async function loadDashboard(force=false){return withPageLoading(async()=>{const res=await api('getExecutiveDashboard',{p1:period(),p2:comparePeriod()},'GET',{force,ttl:force?0:undefined});state.dashboard=res;state.kpi=Array.isArray(res?.kpi)?res.kpi:[];renderKPIs();renderInsight();renderTargetSummary();renderFinancialIntelligence();await loadTrendsForDashboard(force);});}
  function renderKPIs(){const c=$('kpiGrid');if(!state.kpi.length){c.innerHTML='<div class="empty-state">Tidak ada data KPI pada periode ini.</div>';return;}const icons={'TOTAL ASET':'fa-building-columns','KREDIT':'fa-hand-holding-dollar','TOTAL DPK':'fa-vault','PENDAPATAN':'fa-arrow-trend-up','BIAYA':'fa-scissors','LABA/RUGI':'fa-chart-line'};c.innerHTML=state.kpi.filter(k=>['TOTAL ASET','KREDIT','TOTAL DPK','PENDAPATAN','BIAYA','LABA/RUGI'].includes(k.label)).map(k=>{const isCost=String(k.label).includes('BIAYA');const favorable=isCost?Number(k.diffPrev)<=0:Number(k.diffPrev)>=0;const diff=Number(k.diffPrev)||0;return `<article class="kpi-card" data-kpi-label="${escapeHTML(k.label)}" role="button" tabindex="0" aria-label="Buka rincian ${escapeHTML(k.label)}"><div class="kpi-top"><span class="kpi-label">${escapeHTML(k.label)}</span><span class="kpi-actions"><button type="button" class="kpi-favorite ${getFavorites().includes(k.label)?'is-favorite':''}" data-favorite-kpi="${escapeHTML(k.label)}" aria-label="Tambah/hapus favorit ${escapeHTML(k.label)}" title="Favorit"><i class="fa-${getFavorites().includes(k.label)?'solid':'regular'} fa-star"></i></button><span class="kpi-icon"><i class="fa-solid ${icons[k.label]||'fa-chart-pie'}"></i></span></span></div><div class="kpi-value">${state.dashboardMode==='analyst'?idr(k.val,2):moneyCompact(k.val)}</div><div class="kpi-bottom"><span class="kpi-change ${favorable?'positive':(diff===0?'neutral':'negative')}"><i class="fa-solid ${diff>=0?'fa-arrow-trend-up':'fa-arrow-trend-down'}"></i> ${pct(k.pctPrev)}</span><span class="kpi-target">Target ${Number(k.target)?moneyCompact(k.target):'Belum ditetapkan'}<br><b>${pct(k.ach)} tercapai</b></span></div></article>`}).join('');}
  function renderInsight(){const k=(label)=>Number(state.kpi.find(x=>x.label===label)?.val)||0;const laba=state.kpi.find(x=>x.label==='LABA/RUGI');const dpk=k('TOTAL DPK'),credit=k('KREDIT');const ldr=dpk?credit/dpk*100:null;let msg='Data berhasil dimuat. Tinjau perubahan indikator dan rekonsiliasi dengan sumber resmi.';if(laba){if(Number(laba.diffPrev)>0)msg=`Laba/rugi meningkat ${moneyCompact(laba.diffPrev)} dibandingkan periode pembanding.`;else if(Number(laba.diffPrev)<0)msg=`Laba/rugi menurun ${moneyCompact(Math.abs(laba.diffPrev))} dibandingkan periode pembanding.`;else msg='Laba/rugi tidak berubah dibandingkan periode pembanding atau data pembanding bernilai sama.';}if(ldr!==null)msg+=` Rasio kredit terhadap DPK indikatif ${pct(ldr)}; interpretasikan sesuai definisi dan cakupan data sumber.`;$('insightText').textContent=msg;}
  function renderTargetSummary(){const c=$('targetSummary');const items=state.kpi.filter(x=>Number(x.target)!==0).slice(0,6);c.innerHTML=items.length?items.map(x=>`<div class="summary-row"><span>${escapeHTML(x.label)}</span><strong>${pct(x.ach)}<br><small class="muted">${moneyCompact(x.val)} / ${moneyCompact(x.target)}</small></strong></div>`).join(''):'<div class="empty-state">Target belum tersedia atau bernilai nol.</div>';}
  async function loadTrendsForDashboard(force=false){try{const data=await api('getTrendSeries',{},'GET',{force});state.trends=data;drawTrend('mainTrendChart',data);}catch(e){$('targetSummary').insertAdjacentHTML('beforeend',`<p class="muted">Tren belum tersedia: ${escapeHTML(e.message)}</p>`);}}
  async function loadRBB(force=false){return withPageLoading(async()=>{const p=period();const [rbb,renbis,detail,actions]=await Promise.all([api('getLaporanKinerja',{p1:p},'GET',{force}),api('getRenbisAchievement',{p1:p},'GET',{force}),api('getRenbisDetail',{p1:p},'GET',{force}),api('getActionItems',{p1:p},'GET',{force})]);state.rbb=rbb;state.renbis=Array.isArray(renbis)?renbis:[];state.rbbDetail=Array.isArray(detail)?detail:[];state.actions=Array.isArray(actions)?actions:[];renderRBB();renderActions();});}
  function renderRBB(){const rows=state.rbb?.rows||[];$('rbbKpis').innerHTML=[['Total skor',money(state.rbb?.totalSkor||0)],['Kesimpulan',state.rbb?.kesimpulan?.rank||'—'],['Indikator',rows.filter(r=>r.type==='item'||r.type==='aggregate').length]].map(([l,v])=>`<article class="kpi-card"><div class="kpi-label">${escapeHTML(l)}</div><div class="kpi-value">${escapeHTML(v)}</div></article>`).join('');$('rbbBody').innerHTML=rows.length?rows.map(r=>`<tr data-search="${escapeHTML(r.label).toLowerCase()}"><td>${r.type==='header'?`<strong>${escapeHTML(r.label)}</strong>`:escapeHTML(r.label)}</td><td class="num">${r.bobot==null?'—':money(r.bobot)}</td><td class="num">${r.type==='header'?'—':(r.targetMissing?'Belum ditetapkan':money(r.target,2))}</td><td class="num">${r.type==='header'?'—':money(r.actual,2)}</td><td class="num">${r.type==='header'?'—':pct(r.ach)}</td><td>${escapeHTML(r.predikat||'—')}</td><td class="num">${r.skor==null?'—':money(r.skor)}</td></tr>`).join(''):'<tr><td colspan="7" class="empty-state">Data scorecard tidak tersedia.</td></tr>';$('rbbConclusion').hidden=!state.rbb?.kesimpulan;$('rbbConclusion').innerHTML=state.rbb?.kesimpulan?`<strong>Kesimpulan backend:</strong> ${escapeHTML(state.rbb.kesimpulan.rank||'—')} · ${escapeHTML(state.rbb.kesimpulan.reward||'')}`:'';$('renbisBody').innerHTML=state.renbis.length?state.renbis.map(r=>`<tr><td>${escapeHTML(r.label)}</td><td class="num">${Number(r.target)?money(r.target,2):'Belum ditetapkan'}</td><td class="num">${money(r.actual,2)}</td><td class="num">${Number(r.target)?pct(r.ach):'—'}</td><td class="num">${Number(r.target)?money((Number(r.actual)||0)-(Number(r.target)||0),2):'—'}</td></tr>`).join(''):'<tr><td colspan="5" class="empty-state">Target atau realisasi RENBIS belum tersedia.</td></tr>';filterRBB();}
  function filterRBB(){const q=$('rbbSearch').value.toLowerCase();document.querySelectorAll('#rbbBody tr').forEach(tr=>tr.hidden=!!q&&!String(tr.dataset.search||tr.textContent).toLowerCase().includes(q));}
  async function loadAudit(force=false){return withPageLoading(async()=>{const [xray,movers,hierarchy]=await Promise.all([api('getFinancialXRay',{p1:period(),p2:comparePeriod()},'GET',{force}),api('getTopMovers',{p1:period(),p2:comparePeriod()},'GET',{force}),api('getHierarchyImpact',{p1:period()},'GET',{force})]);state.xray=Array.isArray(xray?.rows)?xray.rows:[];state.xrayMeta=xray;state.movers=movers;state.hierarchy=hierarchy;renderAudit();renderMovers(movers);renderHierarchy();renderFinancialIntelligence();});}
  function renderAudit(){const q=$('auditSearch').value.trim().toLowerCase(),dir=$('auditDirection').value,mat=Number($('auditMateriality').value)||0;const rows=state.xray.filter(r=>(!q||`${r.gl} ${r.desc}`.toLowerCase().includes(q))&&(dir==='all'||(dir==='up'?Number(r.diff)>0:Number(r.diff)<0))&&Math.abs(Number(r.diff)||0)>=mat);$('auditPeriodLabel').textContent=`${state.xrayMeta?.period||period()} dibanding ${state.xrayMeta?.comparePeriod||comparePeriod()||'—'}`;$('auditCount').textContent=`${rows.length} akun`;$('auditBody').innerHTML=rows.length?rows.map(r=>`<tr><td>${escapeHTML(r.gl)}</td><td>${escapeHTML(r.desc)}</td><td class="num">${idr(r.curr)}</td><td class="num">${idr(r.prev)}</td><td class="num ${Number(r.diff)>=0?'positive':'negative'}">${idr(r.diff)}</td><td class="num">${Number(r.prev)===0?'—':pct(r.pct)}</td></tr>`).join(''):'<tr><td colspan="6" class="empty-state">Tidak ada akun sesuai filter.</td></tr>';paginateTable('auditTable');}
  function renderMovers(data){const gains=data?.gainers||[],losses=data?.losers||[];$('auditMovers').innerHTML=[['Kenaikan terbesar',gains,'positive'],['Penurunan terbesar',losses,'negative']].map(([title,arr,cl])=>`<div class="mover-card"><h4>${title}</h4>${arr.length?arr.map(x=>`<div class="summary-row"><span>${escapeHTML(x.label)}</span><strong class="${cl}">${idr(x.diff*1000000)}<br><small>${pct(x.pct)}</small></strong></div>`).join(''):'<p>Tidak ada data perubahan yang tersedia.</p>'}</div>`).join('');const all=[...gains,...losses];$('moversBody').innerHTML=all.length?all.map(x=>`<tr><td>${escapeHTML(x.label)}</td><td class="num">${idr(x.val*1000000)}</td><td class="num ${Number(x.diff)>=0?'positive':'negative'}">${idr(x.diff*1000000)}</td><td class="num">${pct(x.pct)}</td><td>${Number(x.diff)>=0?'Naik':'Turun'}</td></tr>`).join(''):'<tr><td colspan="5" class="empty-state">Tidak ada perubahan untuk ditampilkan.</td></tr>';drawMovers(all);paginateTable('moversTable');}
  function renderHierarchy(){const root=state.hierarchy;if(!root){$('hierarchyTree').innerHTML='<div class="empty-state">Hierarki belum tersedia.</div>';return;}const walk=(node,depth=0)=>`<div class="summary-row" style="padding-left:${Math.min(depth,4)*14}px"><span>${depth?'↳ ':''}${escapeHTML(node.name||'Komponen')}</span><strong>${idr((Number(node.value)||0)*1000000)}</strong></div>${(node.children||[]).map(child=>walk(child,depth+1)).join('')}`;$('hierarchyTree').innerHTML=walk(root);}
  const KPI_FORMULAS={'TOTAL ASET':'10000','KREDIT':'15000','TOTAL DPK':'21500 + 22000 + 22500','PENDAPATAN':'40001 + 48000','BIAYA':'50001 + 58000','LABA/RUGI':'31000 / 78500 atau pendapatan dikurangi beban'};
  async function openKpiDetail(label){try{if(!state.xrayMeta)await loadAudit(false);const k=state.kpi.find(x=>x.label===label);if(!k)return;const codes=({'TOTAL ASET':['10000'],'KREDIT':['15000'],'TOTAL DPK':['21500','22000','22500'],'PENDAPATAN':['40001','48000'],'BIAYA':['50001','58000'],'LABA/RUGI':['31000','78500']})[label]||[];const rows=state.xray.filter(r=>codes.includes(String(r.gl)));$('detailTitle').textContent=`Rincian KPI — ${label}`;$('detailContent').innerHTML=`<div class="summary-list"><div class="summary-row"><span>Periode</span><strong>${escapeHTML(period()||'—')}</strong></div><div class="summary-row"><span>Nilai</span><strong>${idr(k.val)}</strong></div><div class="summary-row"><span>Periode pembanding</span><strong>${escapeHTML(comparePeriod()||'—')}</strong></div><div class="summary-row"><span>Nilai pembanding</span><strong>${idr(k.prev)}</strong></div><div class="summary-row"><span>Selisih</span><strong class="${Number(k.diffPrev)>=0?'positive':'negative'}">${idr(k.diffPrev)}</strong></div><div class="summary-row"><span>Perubahan</span><strong>${pct(k.pctPrev)}</strong></div><div class="summary-row"><span>Target</span><strong>${Number(k.target)?idr(k.target):'Belum ditetapkan'}</strong></div><div class="summary-row"><span>Pencapaian</span><strong>${pct(k.ach)}</strong></div><div class="summary-row"><span>Formula referensi</span><strong>${escapeHTML(KPI_FORMULAS[label]||'Lihat master formula backend')}</strong></div></div><h4>Akun terkait yang ditemukan</h4><div class="table-wrap"><table><thead><tr><th>Kode</th><th>Nama akun</th><th>Nilai</th><th>Selisih</th></tr></thead><tbody>${rows.length?rows.map(r=>`<tr><td>${escapeHTML(r.gl)}</td><td>${escapeHTML(r.desc)}</td><td>${idr(r.curr)}</td><td>${idr(r.diff)}</td></tr>`).join(''):'<tr><td colspan="4" class="empty-state">Akun terkait tidak ditemukan dalam data yang dimuat. Gunakan Financial Audit untuk menelusuri seluruh akun.</td></tr>'}</tbody></table></div><p class="muted">Rincian menggunakan mapping akun referensi yang disertakan di UI. Validasi formula terhadap master resmi sebelum mengambil keputusan.</p>`;const d=$('detailDialog');if(!d.open)d.showModal();}catch(e){apiError(e.message)}}
  async function saveAction(e){e.preventDefault();const payload={periode:period(),indikator:$('actionIndicator').value.trim(),owner:$('actionOwner').value.trim(),rencana:$('actionPlan').value.trim(),dueDate:$('actionDue').value};if(!payload.periode){toast('Pilih periode terlebih dahulu.','error');return;}if(!payload.indikator||!payload.owner||!payload.rencana||!payload.dueDate){toast('Lengkapi seluruh data tindak lanjut.','error');return;}if(!await confirmAction('Tambah tindak lanjut?',`Simpan tindak lanjut untuk indikator “${payload.indikator}”?`))return;try{const r=await mutate('saveActionItem',payload);if(r?.status==='error')throw new Error(r.message||'Gagal menyimpan tindak lanjut');toast(r?.message||'Tindak lanjut disimpan.','success');$('actionForm').reset();await loadRBB(true);}catch(err){apiError(err.message)}}
  function renderActions(){const rows=state.actions||[];const statuses=['Belum dimulai','Berjalan','Tertunda','Selesai'];$('actionBody').innerHTML=rows.length?rows.map(x=>`<tr><td>${escapeHTML(x.indikator)}</td><td>${escapeHTML(x.rencana)}</td><td>${escapeHTML(x.owner)}</td><td>${escapeHTML(x.dueDate||'—')}</td><td><select aria-label="Status tindak lanjut" data-action-status="${Number(x.row)}">${statuses.map(st=>`<option value="${st}" ${x.status===st?'selected':''}>${st}</option>`).join('')}</select></td><td><button class="btn btn-secondary" data-update-action="${Number(x.row)}">Simpan status</button></td></tr>`).join(''):'<tr><td colspan="6" class="empty-state">Belum ada tindak lanjut pada periode ini.</td></tr>';document.querySelectorAll('[data-update-action]').forEach(b=>b.addEventListener('click',()=>updateActionStatus(Number(b.dataset.updateAction))));}
  async function updateActionStatus(row){const select=document.querySelector(`[data-action-status="${row}"]`);if(!select)return;try{const r=await mutate('updateActionItem',{rowNumber:row,status:select.value});if(r?.status==='error')throw new Error(r.message||'Gagal memperbarui status');toast(r?.message||'Status diperbarui.','success');await loadRBB(true);}catch(e){apiError(e.message)}}
  async function loadTrends(force=false){return withPageLoading(async()=>{const [trends,movers]=await Promise.all([api('getTrendSeries',{},'GET',{force}),api('getTopMovers',{p1:period(),p2:comparePeriod()},'GET',{force})]);state.trends=trends;state.movers=movers;drawTrend('historyChart',trends);renderMovers(movers);});}
  function drawTrend(id,data){const el=$(id);if(!el||!window.Chart||!data)return;const datasets=(data.series||[]).map((s,i)=>({label:s.name,data:s.data||[],borderColor:[getCss('--primary'),getCss('--success'),getCss('--warning')][i%3],backgroundColor:'transparent',tension:.28,pointRadius:3,borderWidth:2}));makeChart(id,{type:'line',data:{labels:data.periods||[],datasets},options:chartOptions()});}
  function drawMovers(arr){if(!window.Chart)return;makeChart('moversChart',{type:'bar',data:{labels:arr.map(x=>x.label),datasets:[{label:'Perubahan (juta)',data:arr.map(x=>x.diff),backgroundColor:arr.map(x=>Number(x.diff)>=0?getCss('--success'):getCss('--danger')),borderRadius:5}]},options:{...chartOptions(),indexAxis:'y',plugins:{...chartOptions().plugins,legend:{display:false}}}});}
  function chartOptions(){return {responsive:true,maintainAspectRatio:false,interaction:{mode:'index',intersect:false},plugins:{legend:{position:'bottom',labels:{color:getCss('--muted'),usePointStyle:true,boxWidth:7}},tooltip:{callbacks:{label:c=>`${c.dataset.label}: ${idr(Number(c.raw)*1000000)}`}}},scales:{x:{ticks:{color:getCss('--muted'),maxRotation:0},grid:{color:getCss('--line')}},y:{ticks:{color:getCss('--muted')},grid:{color:getCss('--line')}}}};}
  function makeChart(id,config){const el=$(id);if(!el||!window.Chart)return;if(state.charts[id])state.charts[id].destroy();state.charts[id]=new Chart(el.getContext('2d'),config);}
  async function loadHealth(force=false){return withPageLoading(async()=>{if(!state.kpi.length)await loadDashboard(force);const k=state.kpi;const vals=Object.fromEntries(k.map(x=>[x.label,Number(x.val)||0]));const dpk=vals['TOTAL DPK']||0,credit=vals.KREDIT||0,rev=vals.PENDAPATAN||0,cost=vals.BIAYA||0,profit=vals['LABA/RUGI']||rev-cost;const ratios=[['LDR indikatif',dpk?credit/dpk*100:null],['BOPO indikatif',rev?cost/rev*100:null],['Laba / pendapatan',rev?profit/rev*100:null]];$('ratioGrid').innerHTML=ratios.map(([l,v])=>`<article class="kpi-card"><div class="kpi-label">${l}</div><div class="kpi-value">${v===null?'—':pct(v)}</div><small class="muted">Dihitung dari KPI yang tersedia</small></article>`).join('');$('dupontSummary').innerHTML=[['Pendapatan',moneyCompact(rev)],['Beban',moneyCompact(cost)],['Laba/rugi backend',moneyCompact(vals['LABA/RUGI']||0)],['Aset',moneyCompact(vals['TOTAL ASET']||0)]].map(([l,v])=>`<div class="summary-row"><span>${l}</span><strong>${v}</strong></div>`).join('');});}
  function runSimulation(){const n=id=>Number($(id).value)||0;const get=label=>Number(state.kpi.find(k=>k.label===label)?.val)||0;const baseCredit=get('KREDIT'),baseDpk=get('TOTAL DPK'),baseRev=get('PENDAPATAN'),baseCost=get('BIAYA'),baseProfit=get('LABA/RUGI')||baseRev-baseCost;const credit=baseCredit*(1+n('simCredit')/100),dpk=baseDpk*(1+n('simDpk')/100),rev=baseRev*(1+n('simRevenue')/100),cost=baseCost*(1+n('simExpense')/100),profit=rev-cost;const fmt=(v)=>moneyCompact(v);$('simulationResult').innerHTML=`<div class="summary-row"><span>Kredit simulasi</span><strong>${fmt(credit)}</strong></div><div class="summary-row"><span>DPK simulasi</span><strong>${fmt(dpk)}</strong></div><div class="summary-row"><span>Pendapatan simulasi</span><strong>${fmt(rev)}</strong></div><div class="summary-row"><span>Beban simulasi</span><strong>${fmt(cost)}</strong></div><div class="summary-row"><span>Laba indikatif simulasi</span><strong>${fmt(profit)}</strong></div><div class="summary-row"><span>Perubahan laba terhadap basis</span><strong class="${profit>=baseProfit?'positive':'negative'}">${fmt(profit-baseProfit)}</strong></div><small>Model sederhana: perubahan beban dan pendapatan diterapkan secara langsung. Tidak memasukkan pajak, risiko kredit, perubahan struktur aset/liabilitas, atau keterkaitan antarvariabel.</small>`;}
  async function loadCost(force=false){return withPageLoading(async()=>{const res=await api('getCostAnalysis',{p1:period()},'GET',{force});state.costs=res;renderCosts();});}
  function renderCosts(){const data=state.costs||{},q=$('costSearch').value.toLowerCase(),expenses=(data.topExpenses||[]).filter(x=>!q||`${x.gl} ${x.desc}`.toLowerCase().includes(q));$('costKpis').innerHTML=[['Beban bunga',moneyCompact(data.totalBebanBunga)],['Overhead',moneyCompact(data.totalOverhead)],['Cost-to-income',pct(data.costToIncome)]].map(([l,v])=>`<article class="kpi-card"><div class="kpi-label">${l}</div><div class="kpi-value">${v}</div></article>`).join('');$('costBody').innerHTML=expenses.length?expenses.map(x=>`<tr><td>${escapeHTML(x.gl)}</td><td>${escapeHTML(x.desc)}</td><td class="num">${idr(x.curr)}</td><td class="num ${Number(x.diff)>=0?'negative':'positive'}">${idr(x.diff)}</td><td class="num">${Number(x.pct)===0&&Number(x.diff)!==0?'—':pct(x.pct)}</td></tr>`).join(''):'<tr><td colspan="5" class="empty-state">Data biaya tidak tersedia atau tidak cocok dengan pencarian.</td></tr>';paginateTable('costTable');}
  async function loadDatabase(force=false){return withPageLoading(async()=>{const rows=await api('getNeracaList',{},'GET',{force});state.database=Array.isArray(rows)?rows:[];$('databaseBody').innerHTML=state.database.length?state.database.map(x=>`<tr><td>${escapeHTML(x.periode)}</td><td class="num">${money(x.rows)}</td><td><button class="btn btn-danger" data-delete-period="${escapeHTML(x.periode)}"><i class="fa-solid fa-trash"></i> Hapus periode</button></td></tr>`).join(''):'<tr><td colspan="3" class="empty-state">Belum ada data neraca.</td></tr>';document.querySelectorAll('[data-delete-period]').forEach(b=>b.addEventListener('click',()=>deletePeriod(b.dataset.deletePeriod)));});}
  function readImportFile(file){if(!file)return;if(!/\.txt$/i.test(file.name)&&file.type!=='text/plain'){toast('Pilih file TXT yang valid.','error');return;}if(file.size>10*1024*1024){toast('Ukuran file melebihi batas 10 MB.','error');return;}const reader=new FileReader();reader.onload=()=>{const text=String(reader.result||'');const lines=text.split(/\r?\n/);const dateLine=lines.slice(0,50).find(x=>/(?:TANGGAL|TGL)\s*:/i.test(x));const accounts=lines.filter(x=>/\d{4,}\s*-/.test(x));state.selectedImport={name:file.name,content:text,lines:lines.length,accounts:accounts.length,dateLine:dateLine||'Tanggal tidak terdeteksi sebelum validasi backend'};$('importPreview').hidden=false;$('importPreview').innerHTML=`<div class="import-stepper"><span class="is-done"><i class="fa-solid fa-circle-check"></i> 1. File dipilih</span><span class="is-current"><i class="fa-solid fa-magnifying-glass"></i> 2. Pemeriksaan awal</span><span><i class="fa-solid fa-shield-halved"></i> 3. Validasi backend</span></div><div class="conclusion-box"><strong>Pratinjau file: ${escapeHTML(file.name)}</strong><div class="summary-row"><span>Ukuran file</span><strong>${(file.size/1024).toLocaleString('id-ID',{maximumFractionDigits:1})} KB</strong></div><div class="summary-row"><span>Jumlah baris file</span><strong>${money(lines.length)}</strong></div><div class="summary-row"><span>Baris yang tampak seperti akun</span><strong>${money(accounts.length)}</strong></div><div class="summary-row"><span>Baris tanggal terdeteksi</span><strong>${escapeHTML(dateLine||'Tidak terdeteksi')}</strong></div><p class="muted">Pratinjau ini hanya pemeriksaan awal. Backend tetap harus memvalidasi format, keseimbangan, dan duplikasi sebelum menulis data.</p></div>`;$('confirmImport').disabled=false;$('cancelImport').disabled=false;};reader.onerror=()=>toast('File gagal dibaca.','error');reader.readAsText(file);}
  async function confirmImport(){if(!state.selectedImport)return;const ok=await confirmAction('Konfirmasi impor','Backend akan memproses file dan mengganti data pada periode yang sama jika aturan impor mengizinkan. Pastikan backup tersedia.');if(!ok)return;loader(true,'Memvalidasi dan mengimpor neraca…');try{const res=await mutate('uploadNeracaTxt',{fileContent:state.selectedImport.content});if(res?.status==='error')throw new Error(res.message||'Impor gagal');toast(res?.message||'Impor berhasil.','success');cancelImport();await loadDatabase(true);const periods=await api('getPeriodList',{},'GET',{force:true,ttl:0});state.periods=periods||[];fillPeriodSelectors();}catch(e){apiError(e.message)}finally{loader(false)}}
  function cancelImport(){state.selectedImport=null;$('fileUpload').value='';$('importPreview').hidden=true;$('importPreview').innerHTML='';$('confirmImport').disabled=true;$('cancelImport').disabled=true;}
  async function deletePeriod(p){if(!await confirmAction('Hapus periode neraca?',`Seluruh baris untuk periode ${p} akan dihapus. Pastikan Anda memiliki backup dan kewenangan yang sesuai.`))return;loader(true,'Menghapus periode…');try{const r=await mutate('deleteNeracaPeriod',{periode:p});if(r?.status==='error')throw new Error(r.message||'Penghapusan gagal');toast(r?.message||'Periode dihapus.','success');state.periods=await api('getPeriodList',{},'GET',{force:true,ttl:0});fillPeriodSelectors();await loadDatabase(true);}catch(e){apiError(e.message)}finally{loader(false)}}
  async function loadManual(force=false){return withPageLoading(async()=>{const p=$('manualPeriod').value||period();if(!p){$('manualBody').innerHTML='<tr><td colspan="4" class="empty-state">Pilih atau impor periode terlebih dahulu.</td></tr>';return;}const rows=await api('getManualInputList',{p1:p},'GET',{force});state.manual=Array.isArray(rows)?rows:[];$('manualBody').innerHTML=state.manual.length?state.manual.map(x=>`<tr><td>${escapeHTML(p)}</td><td>${escapeHTML(x.komponen)}</td><td class="num">${money(x.nilai,4)}</td><td><button class="btn btn-danger" data-delete-manual="${Number(x.row)}">Hapus</button></td></tr>`).join(''):'<tr><td colspan="4" class="empty-state">Belum ada input manual pada periode ini.</td></tr>';document.querySelectorAll('[data-delete-manual]').forEach(b=>b.addEventListener('click',()=>deleteManual(Number(b.dataset.deleteManual))));});}
  async function saveManual(e){e.preventDefault();const p=$('manualPeriod').value,c=$('manualComponent').value,v=$('manualValue').value;if(!p||!c||v===''||!Number.isFinite(Number(v))){toast('Periksa periode, komponen, dan nilai.','error');return;}if(!await confirmAction('Simpan input manual?',`Simpan ${c} = ${v} untuk periode ${p}?`))return;loader(true,'Menyimpan input…');try{const r=await mutate('saveManualInput',{periode:p,komponen:c,nilai:Number(v)});if(r?.status==='error')throw new Error(r.message||'Simpan gagal');$('manualValue').value='';toast('Input manual disimpan.','success');await loadManual(true);invalidateCache();}catch(e){apiError(e.message)}finally{loader(false)}}
  async function deleteManual(row){if(!await confirmAction('Hapus input manual?',`Baris data ${row} akan dihapus. Tindakan ini perlu kewenangan yang sesuai.`))return;try{const r=await mutate('deleteManualInput',{rowNumber:row});if(r?.status==='error')throw new Error(r.message||'Hapus gagal');toast('Input manual dihapus.','success');await loadManual(true)}catch(e){apiError(e.message)}}
  const targetNames=['Aset','Kredit','Konsumtif','Produktif','Total DPK','Tabungan','Deposito','Giro','Pendapatan','Beban','Laba sebelum pajak','NPL','Ekstrakom','BOPO'];
  async function loadTargets(force=false){return withPageLoading(async()=>{const year=Number($('inputYear').value);if(!year||year<2000||year>2100)throw new Error('Tahun tidak valid.');const res=await api('loadTargetRenbisInput',{p1:String(year)},'GET',{force});state.targets=res||{};renderTargets();});}
  function renderTargets(){const q=['MARET','JUNI','SEPTEMBER','DESEMBER'];const keys=Object.keys(state.targets||{});const names=keys.length?keys:targetNames;$('targetInputBody').innerHTML=names.map(name=>{const vals=state.targets?.[name]||[0,0,0,0];return `<tr><td>${escapeHTML(name)}</td>${q.map((_,i)=>`<td><input aria-label="${escapeHTML(name)} ${q[i]}" type="number" step="any" data-target-name="${escapeHTML(name)}" data-quarter="${i}" value="${Number(vals[i])||0}" /></td>`).join('')}</tr>`}).join('');}
  async function saveTargets(){const year=Number($('inputYear').value);const data={};document.querySelectorAll('[data-target-name]').forEach(el=>{const name=el.dataset.targetName,idx=Number(el.dataset.quarter);if(!data[name])data[name]=[0,0,0,0];data[name][idx]=Number(el.value)||0;});if(!Object.keys(data).length){toast('Tidak ada target untuk disimpan.','error');return;}if(!await confirmAction('Simpan target RENBIS?',`Simpan perubahan target tahun ${year}? Pastikan target sudah disetujui.`))return;loader(true,'Menyimpan target…');try{const r=await mutate('saveTargetRenbisInput',{tahun:year,dataJSON:JSON.stringify(data)});if(r?.status==='error')throw new Error(r.message||'Simpan target gagal');toast('Target RENBIS tersimpan.','success');await loadTargets(true);}catch(e){apiError(e.message)}finally{loader(false)}}
  async function buildReport(type='executive',force=false){state.reportType=type;if(type==='rbb'&&!state.rbb)await loadRBB(force);if(type==='audit'&&!state.xrayMeta)await loadAudit(force);if(type==='cost'&&!state.costs)await loadCost(force);$('reportPreview').dataset.ready='1';let title='',html='';if(type==='executive'){title='Laporan Eksekutif';html=`<h2>${title}</h2><p>Periode: ${escapeHTML(period())} · Pembanding: ${escapeHTML(comparePeriod()||'—')}</p><p>${escapeHTML($('insightText').textContent)}</p><table><thead><tr><th>Indikator</th><th>Nilai</th><th>Pembanding</th><th>Perubahan</th><th>Target</th><th>Pencapaian</th></tr></thead><tbody>${state.kpi.map(x=>`<tr><td>${escapeHTML(x.label)}</td><td>${idr(x.val)}</td><td>${idr(x.prev)}</td><td>${idr(x.diffPrev)}</td><td>${idr(x.target)}</td><td>${pct(x.ach)}</td></tr>`).join('')}</tbody></table>`;}else if(type==='rbb'){title='Laporan RBB';html=`<h2>${title}</h2><p>Periode: ${escapeHTML(period())}</p><p>Kesimpulan: ${escapeHTML(state.rbb?.kesimpulan?.rank||'Data belum dimuat')}</p><table><thead><tr><th>Indikator</th><th>Target</th><th>Realisasi</th><th>Pencapaian</th><th>Predikat</th><th>Skor</th></tr></thead><tbody>${(state.rbb?.rows||[]).map(x=>`<tr><td>${escapeHTML(x.label)}</td><td>${money(x.target)}</td><td>${money(x.actual)}</td><td>${pct(x.ach)}</td><td>${escapeHTML(x.predikat||'—')}</td><td>${money(x.skor)}</td></tr>`).join('')}</tbody></table>`;}else if(type==='audit'){title='Laporan Perubahan Akun';html=`<h2>${title}</h2><p>${escapeHTML(state.xrayMeta?.period||period())} dibanding ${escapeHTML(state.xrayMeta?.comparePeriod||comparePeriod())}</p><table><thead><tr><th>Kode</th><th>Akun</th><th>Saat ini</th><th>Pembanding</th><th>Selisih</th><th>%</th></tr></thead><tbody>${state.xray.map(x=>`<tr><td>${escapeHTML(x.gl)}</td><td>${escapeHTML(x.desc)}</td><td>${idr(x.curr)}</td><td>${idr(x.prev)}</td><td>${idr(x.diff)}</td><td>${pct(x.pct)}</td></tr>`).join('')}</tbody></table>`;}else{title='Laporan Biaya';html=`<h2>${title}</h2><p>Periode: ${escapeHTML(state.costs?.period||period())}</p><p>Beban bunga: ${idr(state.costs?.totalBebanBunga)} · Overhead: ${idr(state.costs?.totalOverhead)} · Cost-to-income: ${pct(state.costs?.costToIncome)}</p><table><thead><tr><th>Kode</th><th>Akun</th><th>Saldo</th><th>Selisih</th><th>%</th></tr></thead><tbody>${(state.costs?.topExpenses||[]).map(x=>`<tr><td>${escapeHTML(x.gl)}</td><td>${escapeHTML(x.desc)}</td><td>${idr(x.curr)}</td><td>${idr(x.diff)}</td><td>${pct(x.pct)}</td></tr>`).join('')}</tbody></table>`;}const meta=`<div class="report-metadata"><span><strong>PRIME Ledger</strong> · Executive Banking Suite</span><span>Periode: ${escapeHTML(period()||'—')} · Pembanding: ${escapeHTML(comparePeriod()||'—')}</span><span>Dibuat: ${escapeHTML(new Date().toLocaleString('id-ID'))}</span><span>Status: data analitis; rekonsiliasi dengan sumber resmi sebelum distribusi.</span></div>`;$('reportPreview').innerHTML=(html?meta+html:'<div class="empty-state">Belum ada data untuk laporan ini.</div>');return Promise.resolve();}
  function downloadReportCsv(){const table=$('reportPreview').querySelector('table');if(!table){toast('Pilih laporan terlebih dahulu.','error');return;}downloadBlob(tableToCsv(table),`prime-ledger-${state.reportType}-${period()||'data'}.csv`,'text/csv;charset=utf-8;');}
  function exportTable(id){const table=$(id);if(!table){toast('Tabel belum tersedia.','error');return;}downloadBlob(tableToCsv(table),`prime-ledger-${id}-${period()||'data'}.csv`,'text/csv;charset=utf-8;');}
  function tableToCsv(table){const safe=v=>{let x=String(v??'').replace(/\s+/g,' ').trim();if(/^[=+@\t\r]/.test(x)||(/^-/ .test(x)&&! /^-?\d+(?:[.,]\d+)?$/.test(x)))x="'"+x;return '"'+x.replace(/"/g,'""')+'"';};return '\ufeff'+Array.from(table.querySelectorAll('tr')).map(tr=>Array.from(tr.querySelectorAll('th,td')).map(td=>safe(td.innerText)).join(',')).join('\r\n');}
  function downloadBlob(content,name,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function updateDashboardModeButton(){const b=$('dashboardModeToggle');if(!b)return;const analyst=state.dashboardMode==='analyst';b.setAttribute('aria-pressed',String(analyst));b.innerHTML=analyst?'<i class="fa-solid fa-gauge-high"></i> Mode Executive':'<i class="fa-solid fa-magnifying-glass-chart"></i> Mode Analyst';b.title=analyst?'Beralih ke ringkasan angka singkat':'Beralih ke angka penuh dan rincian analitis';}
  function toggleDashboardMode(){state.dashboardMode=state.dashboardMode==='analyst'?'executive':'analyst';safeStorageSet('prime_dashboard_mode',state.dashboardMode);updateDashboardModeButton();renderKPIs();toast(state.dashboardMode==='analyst'?'Mode Analyst: nominal KPI ditampilkan lengkap dalam Rupiah.':'Mode Executive: ringkasan KPI kembali ringkas.','success',2600);}
  function sortTableByHeader(table,th){const index=[...th.parentElement.children].indexOf(th);if(index<0)return;const key=`${table.id}:${index}`,direction=state.tableSort[key]==='asc'?'desc':'asc';state.tableSort[key]=direction;const tbody=table.tBodies[0];if(!tbody)return;const rows=[...tbody.rows].filter(r=>!r.querySelector('.empty-state'));const numeric=v=>{let s=String(v||'').replace(/Rp\s*/gi,'').replace(/%/g,'').replace(/\s/g,'');if(!s||s==='—')return NaN;s=s.replace(/\./g,'').replace(',','.');return /^-?\d+(?:\.\d+)?$/.test(s)?Number(s):NaN;};rows.sort((a,b)=>{const av=a.cells[index]?.innerText.trim()||'',bv=b.cells[index]?.innerText.trim()||'',an=numeric(av),bn=numeric(bv);let cmp;if(Number.isFinite(an)&&Number.isFinite(bn))cmp=an-bn;else cmp=av.localeCompare(bv,'id',{numeric:true,sensitivity:'base'});return direction==='asc'?cmp:-cmp;});rows.forEach(r=>tbody.appendChild(r));[...th.parentElement.children].forEach(h=>{h.removeAttribute('aria-sort');h.classList.remove('sort-asc','sort-desc');});th.setAttribute('aria-sort',direction==='asc'?'ascending':'descending');th.classList.add(direction==='asc'?'sort-asc':'sort-desc');if(['auditTable','costTable','moversTable'].includes(table.id)){state.tablePagination[table.id]&&(state.tablePagination[table.id].page=0);paginateTable(table.id);}}

  function paginateTable(id){const table=$(id);if(!table||!table.tBodies[0])return;const wrap=table.closest('.table-wrap');if(!wrap)return;let tools=$(id+'Tools');if(!tools){tools=document.createElement('div');tools.id=id+'Tools';tools.className='table-tools';tools.innerHTML='<label>Baris <select class="table-page-size" aria-label="Jumlah baris per halaman"><option value="10">10</option><option value="25" selected>25</option><option value="50">50</option><option value="100">100</option></select></label><span class="table-page-status"></span><div class="table-page-buttons"><button type="button" class="btn btn-secondary table-prev">Sebelumnya</button><button type="button" class="btn btn-secondary table-next">Berikutnya</button></div><details class="column-chooser-details"><summary>Kolom</summary><div class="column-chooser"></div></details>';wrap.insertAdjacentElement('afterend',tools);tools.querySelector('.table-page-size').addEventListener('change',()=>{const st=state.tablePagination[id]||{page:0,size:25};st.size=Number(tools.querySelector('.table-page-size').value)||25;st.page=0;state.tablePagination[id]=st;paginateTable(id);});tools.querySelector('.table-prev').addEventListener('click',()=>{const st=state.tablePagination[id]||{page:0,size:25};st.page=Math.max(0,st.page-1);state.tablePagination[id]=st;paginateTable(id);});tools.querySelector('.table-next').addEventListener('click',()=>{const st=state.tablePagination[id]||{page:0,size:25};st.page++;state.tablePagination[id]=st;paginateTable(id);});const chooser=tools.querySelector('.column-chooser');[...table.tHead.rows[0].cells].forEach((th,i)=>{const label=document.createElement('label'),cb=document.createElement('input');cb.type='checkbox';cb.checked=true;cb.dataset.column=String(i);const span=document.createElement('span');span.textContent=th.innerText.trim();label.append(cb,span);chooser.append(label);cb.addEventListener('change',()=>{let vis={};try{vis=JSON.parse(safeStorageGet(`prime_columns_${id}`)||'{}')||{};}catch(_){}vis[i]=cb.checked;safeStorageSet(`prime_columns_${id}`,JSON.stringify(vis));applyColumnVisibility(table);});});const savedSize=Number(safeStorageGet(`prime_page_size_${id}`));if([10,25,50,100].includes(savedSize))tools.querySelector('.table-page-size').value=String(savedSize);}
    const sizeSelect=tools.querySelector('.table-page-size');const st=state.tablePagination[id]||(state.tablePagination[id]={page:0,size:Number(sizeSelect.value)||25});st.size=Number(sizeSelect.value)||st.size||25;safeStorageSet(`prime_page_size_${id}`,String(st.size));const rows=[...table.tBodies[0].rows].filter(r=>!r.querySelector('.empty-state'));const total=rows.length,pages=Math.max(1,Math.ceil(total/st.size));st.page=Math.min(Math.max(0,st.page),pages-1);rows.forEach((r,i)=>r.hidden=i<st.page*st.size||i>=(st.page+1)*st.size);table.tBodies[0].querySelectorAll('tr').forEach(r=>{if(r.querySelector('.empty-state'))r.hidden=false;});tools.querySelector('.table-page-status').textContent=total?`Halaman ${st.page+1}/${pages} · ${total.toLocaleString('id-ID')} baris`:'Tidak ada baris';tools.querySelector('.table-prev').disabled=st.page<=0;tools.querySelector('.table-next').disabled=st.page>=pages-1;applyColumnVisibility(table);}
  function applyColumnVisibility(table){const id=table.id;let vis={};try{vis=JSON.parse(safeStorageGet(`prime_columns_${id}`)||'{}')||{};}catch(_){};[...table.rows].forEach(row=>[...row.cells].forEach((cell,i)=>{const hidden=vis[i]===false;cell.hidden=hidden;}));const tools=$(id+'Tools');tools?.querySelectorAll('[data-column]').forEach(cb=>{const index=Number(cb.dataset.column);cb.checked=vis[index]!==false;});}

  const WORKSPACE_KEYS={notifications:'prime_notifications_v1',favorites:'prime_favorites_v1',views:'prime_saved_views_v1',recent:'prime_recent_pages_v1'};
  function readLocalJson(key,fallback=[]){try{const value=JSON.parse(safeStorageGet(key)||'null');return Array.isArray(fallback)?(Array.isArray(value)?value:fallback):(value&&typeof value==='object'?value:fallback);}catch(_){return fallback;}}
  function writeLocalJson(key,value){try{safeStorageSet(key,JSON.stringify(value));}catch(_){}}
  function loadWorkspaceState(){state.notifications=readLocalJson(WORKSPACE_KEYS.notifications,[]).slice(0,30);state.recentPages=readLocalJson(WORKSPACE_KEYS.recent,[]).slice(0,8);}
  function recordNotification(title,message,type='info'){const item={id:`${Date.now()}-${Math.random().toString(36).slice(2,7)}`,title:String(title).slice(0,80),message:String(message).slice(0,220),type,at:new Date().toISOString(),read:false};state.notifications=[item,...(state.notifications||[])].slice(0,30);writeLocalJson(WORKSPACE_KEYS.notifications,state.notifications);renderNotificationBadge();}
  function renderNotificationBadge(){const unread=(state.notifications||[]).filter(n=>!n.read).length;const badge=$('notificationCount');badge.textContent=unread>99?'99+':String(unread);badge.hidden=!unread;}
  function renderNotificationCenter(){const list=$('notificationList');if(!list)return;const items=state.notifications||[];list.innerHTML=items.length?items.map(n=>`<article class="notification-item ${n.read?'is-read':''}"><span class="notification-symbol ${escapeHTML(n.type)}"><i class="fa-solid ${n.type==='error'?'fa-circle-exclamation':n.type==='success'?'fa-circle-check':n.type==='warning'?'fa-triangle-exclamation':'fa-circle-info'}"></i></span><div><strong>${escapeHTML(n.title)}</strong><p>${escapeHTML(n.message)}</p><small>${escapeHTML(new Date(n.at).toLocaleString('id-ID'))}</small></div><button type="button" class="icon-btn notification-read" data-notification-read="${escapeHTML(n.id)}" aria-label="Tandai telah dibaca"><i class="fa-solid fa-check"></i></button></article>`).join(''):'<div class="empty-state">Belum ada aktivitas yang tercatat di browser ini.</div>';list.querySelectorAll('[data-notification-read]').forEach(b=>b.addEventListener('click',()=>{state.notifications=state.notifications.map(n=>n.id===b.dataset.notificationRead?{...n,read:true}:n);writeLocalJson(WORKSPACE_KEYS.notifications,state.notifications);renderNotificationCenter();renderNotificationBadge();}));renderNotificationBadge();}
  function openNotificationCenter(){state.notifications=(state.notifications||[]).map(n=>({...n,read:true}));writeLocalJson(WORKSPACE_KEYS.notifications,state.notifications);renderNotificationCenter();$('notificationDialog').showModal();}
  function clearNotifications(){state.notifications=[];writeLocalJson(WORKSPACE_KEYS.notifications,state.notifications);renderNotificationCenter();toast('Riwayat notifikasi lokal dibersihkan.','success',2600);}
  function recordRecentPage(id){state.recentPages=[id,...(state.recentPages||[]).filter(x=>x!==id)].slice(0,8);writeLocalJson(WORKSPACE_KEYS.recent,state.recentPages);}
  function getFavorites(){return readLocalJson(WORKSPACE_KEYS.favorites,[]);}
  function toggleFavoriteKpi(label){let fav=getFavorites();if(fav.includes(label))fav=fav.filter(x=>x!==label);else fav.unshift(label);writeLocalJson(WORKSPACE_KEYS.favorites,fav);renderKPIs();renderWorkspace();toast(fav.includes(label)?`${label} ditambahkan ke favorit.`:`${label} dihapus dari favorit.`, 'success',2500);}
  function openWorkspace(){renderWorkspace();$('workspaceDialog').showModal();}
  function renderWorkspace(){const views=readLocalJson(WORKSPACE_KEYS.views,[]),fav=getFavorites(),recent=state.recentPages||[];const names={dashboard:'Executive Board',rbb:'RBB Tracker',audit:'Financial Audit',trends:'Market Volatility',health:'Health Check & Simulasi',cost:'Cost Control',reports:'Reporting Hub',database:'Database & Import',manual:'Input Manual',targets:'Target RENBIS'};const row=(label,sub,action,remove='')=>`<div class="workspace-item"><button type="button" class="workspace-open" ${action}><strong>${escapeHTML(label)}</strong><small>${escapeHTML(sub||'')}</small></button>${remove}</div>`;$('savedViewsList').innerHTML=views.length?views.map((v,i)=>row(v.name,`${names[v.page]||v.page} · ${v.period||'tanpa periode'}${v.compare?' vs '+v.compare:''}`,`data-load-view="${i}"`,`<button class="icon-btn" data-delete-view="${i}" aria-label="Hapus tampilan"><i class="fa-solid fa-trash"></i></button>`)).join(''):'<p class="muted">Belum ada tampilan tersimpan.</p>';$('favoritesList').innerHTML=fav.length?fav.map(label=>row(label,'KPI favorit',`data-open-favorite="${escapeHTML(label)}"`)).join(''):'<p class="muted">Belum ada KPI favorit. Klik ikon bintang pada kartu KPI.</p>';$('recentPagesList').innerHTML=recent.length?recent.map(id=>row(names[id]||id,'Halaman terakhir dibuka',`data-open-page="${escapeHTML(id)}"`)).join(''):'<p class="muted">Belum ada halaman terakhir.</p>';$('savedViewsList').querySelectorAll('[data-load-view]').forEach(b=>b.addEventListener('click',()=>loadSavedView(views[Number(b.dataset.loadView)])));$('savedViewsList').querySelectorAll('[data-delete-view]').forEach(b=>b.addEventListener('click',()=>{const i=Number(b.dataset.deleteView);views.splice(i,1);writeLocalJson(WORKSPACE_KEYS.views,views);renderWorkspace();toast('Tampilan tersimpan dihapus.','success',2200);}));$('favoritesList').querySelectorAll('[data-open-favorite]').forEach(b=>b.addEventListener('click',()=>{const label=b.dataset.openFavorite;$('workspaceDialog').close();showPage('dashboard');setTimeout(()=>openKpiDetail(label),100);}));$('recentPagesList').querySelectorAll('[data-open-page]').forEach(b=>b.addEventListener('click',()=>{$('workspaceDialog').close();showPage(b.dataset.openPage);}));}
  function saveCurrentView(){const name=$('savedViewName').value.trim();if(!name){toast('Masukkan nama tampilan terlebih dahulu.','warning');$('savedViewName').focus();return;}const views=readLocalJson(WORKSPACE_KEYS.views,[]);views.unshift({name:name.slice(0,60),page:state.page,period:period(),compare:comparePeriod(),theme:document.body.dataset.theme,at:new Date().toISOString()});writeLocalJson(WORKSPACE_KEYS.views,views.slice(0,20));$('savedViewName').value='';renderWorkspace();toast('Tampilan workspace berhasil disimpan di browser ini.','success');}
  function loadSavedView(view){if(!view)return;if(view.period&&Array.from($('periodSelector').options).some(o=>o.value===view.period))$('periodSelector').value=view.period;if(view.compare&&Array.from($('compareSelector').options).some(o=>o.value===view.compare))$('compareSelector').value=view.compare;if(view.theme&&['dark','light','contrast'].includes(view.theme)){document.body.dataset.theme=view.theme;safeStorageSet('prime_theme',view.theme);updateThemeIcon();}invalidateCache();$('workspaceDialog').close();showPage(view.page||'dashboard');refreshCurrent(true);toast(`Tampilan “${view.name}” dibuka.`,'success',2800);}
  const MENU_ITEMS=[['Executive Board','dashboard','Dashboard eksekutif'],['RBB Tracker','rbb','Target dan scorecard'],['Financial Audit','audit','Perubahan akun dan audit'],['Market Volatility','trends','Tren historis'],['Health Check & Simulasi','health','Rasio dan simulasi'],['Cost Control','cost','Analisis biaya'],['Reporting Hub','reports','Laporan dan ekspor'],['Database & Import','database','Impor data neraca'],['Input Manual','manual','Input komponen manual'],['Target RENBIS','targets','Kelola target']];
  function openCommandPalette(){const d=$('commandDialog');if(!d.open)d.showModal();$('globalSearchInput').value='';renderGlobalSearch();setTimeout(()=>$('globalSearchInput').focus(),30);if((!state.xrayMeta||String(state.xrayMeta.period||'')!==String(period()||'')||(comparePeriod()&&String(state.xrayMeta.comparePeriod||'')!==String(comparePeriod())))&&period())api('getFinancialXRay',{p1:period(),p2:comparePeriod()},'GET',{ttl:30000}).then(data=>{state.xray=Array.isArray(data?.rows)?data.rows:[];state.xrayMeta=data;if($('commandDialog').open)renderGlobalSearch();}).catch(()=>{});}
  function buildSearchItems(){const items=MENU_ITEMS.map(([label,page,desc])=>({kind:'menu',label,sub:desc,page}));(state.kpi||[]).forEach(k=>items.push({kind:'kpi',label:k.label,sub:`KPI · ${idr(k.val)} · periode ${period()}`,value:k.label}));(state.xray||[]).forEach(r=>items.push({kind:'account',label:`${r.gl} — ${r.desc}`,sub:`Saldo ${idr(r.curr)} · perubahan ${idr(r.diff)}`,account:r}));(state.database||[]).forEach(r=>items.push({kind:'period',label:`Periode ${r.periode}`,sub:`${money(r.rows)} baris neraca`,value:r.periode}));return items;}
  function renderGlobalSearch(){const q=$('globalSearchInput').value.trim().toLowerCase(),all=buildSearchItems();const results=q?all.filter(x=>`${x.label} ${x.sub}`.toLowerCase().includes(q)).slice(0,40):MENU_ITEMS.slice(0,6).map(([label,page,sub])=>({kind:'menu',label,sub,page}));state.searchItems=results;state.searchIndex=0;$('globalSearchResults').innerHTML=results.length?results.map((x,i)=>`<button type="button" class="command-result ${i===0?'is-active':''}" data-search-index="${i}"><span class="command-result-icon"><i class="fa-solid ${x.kind==='menu'?'fa-layer-group':x.kind==='account'?'fa-file-invoice-dollar':x.kind==='period'?'fa-calendar-days':'fa-chart-line'}"></i></span><span><strong>${escapeHTML(x.label)}</strong><small>${escapeHTML(x.sub||'')}</small></span><kbd>${x.kind==='menu'?'MENU':x.kind==='account'?'AKUN':x.kind==='period'?'PERIODE':'KPI'}</kbd></button>`).join(''):'<div class="empty-state">Tidak ditemukan. Coba kata kunci atau kode rekening lain.</div>';$('globalSearchResults').querySelectorAll('[data-search-index]').forEach(b=>b.addEventListener('click',()=>activateSearchResult(Number(b.dataset.searchIndex))));}
  function handleGlobalSearchKeys(e){const list=$('globalSearchResults'),buttons=[...list.querySelectorAll('[data-search-index]')];if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if(!buttons.length)return;state.searchIndex=(state.searchIndex+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length;buttons.forEach((b,i)=>b.classList.toggle('is-active',i===state.searchIndex));buttons[state.searchIndex].scrollIntoView({block:'nearest'});}else if(e.key==='Enter'){e.preventDefault();activateSearchResult(state.searchIndex);}}
  function activateSearchResult(index){const item=state.searchItems[index];if(!item)return;$('commandDialog').close();if(item.kind==='menu'){showPage(item.page);return;}if(item.kind==='kpi'){showPage('dashboard');setTimeout(()=>openKpiDetail(item.value),120);return;}if(item.kind==='account'){showPage('audit');setTimeout(()=>{$('auditSearch').value=item.account.gl;renderAudit();},120);return;}if(item.kind==='period'){if(Array.from($('periodSelector').options).some(o=>o.value===item.value))$('periodSelector').value=item.value;refreshCurrent(true);}}
  function renderFinancialIntelligence(){const c=$('intelligenceList');if(!c)return;const xrayIsCurrent=!!state.xrayMeta&&String(state.xrayMeta.period||'')===String(period()||'')&&(!comparePeriod()||String(state.xrayMeta.comparePeriod||'')===String(comparePeriod()));const movers=(xrayIsCurrent?(state.xray||[]):[]).filter(r=>Number.isFinite(Number(r.diff))&&Math.abs(Number(r.diff))>=1000000&&Number.isFinite(Number(r.pct))&&Math.abs(Number(r.pct))>=10).sort((a,b)=>Math.abs(Number(b.diff))-Math.abs(Number(a.diff))).slice(0,5);const kpis=(state.kpi||[]).filter(k=>Number.isFinite(Number(k.diffPrev))&&Math.abs(Number(k.diffPrev))>=1000000).sort((a,b)=>Math.abs(Number(b.diffPrev))-Math.abs(Number(a.diffPrev))).slice(0,3);const rows=[...movers.map(r=>({label:`${r.gl} — ${r.desc}`,detail:`Perubahan ${idr(r.diff)} (${pct(r.pct)})`,value:Number(r.diff)})),...kpis.map(k=>({label:k.label,detail:`Perubahan ${idr(k.diffPrev)} (${pct(k.pctPrev)})`,value:Number(k.diffPrev)}))].slice(0,6);c.innerHTML=rows.length?rows.map(r=>`<div class="intelligence-item"><span class="intelligence-mark ${r.value>=0?'up':'down'}"><i class="fa-solid ${r.value>=0?'fa-arrow-trend-up':'fa-arrow-trend-down'}"></i></span><div><strong>${escapeHTML(r.label)}</strong><p>${escapeHTML(r.detail)}</p><small>Ditandai oleh aturan nominal ≥ Rp1.000.000 dan perubahan ≥ 10% jika data persentase tersedia. Periksa data sumber sebelum menyimpulkan.</small></div></div>`).join(''):'<div class="empty-state">Belum ada perubahan yang memenuhi aturan pemeriksaan atau data pembanding belum tersedia.</div>';}

  async function confirmAction(title,message){const d=$('confirmDialog');$('dialogTitle').textContent=title;$('dialogMessage').textContent=message;if(typeof d.showModal!=='function')return window.confirm(`${title}\n\n${message}`);return new Promise(resolve=>{const handler=()=>{d.removeEventListener('close',handler);resolve(d.returnValue==='confirm')};d.addEventListener('close',handler);d.showModal();});}
  window.addEventListener('error',e=>{console.error('PRIME Ledger UI error',e.error||e.message);}); window.addEventListener('unhandledrejection',e=>{console.error('PRIME Ledger async error',e.reason);toast(e.reason?.message||'Terjadi kesalahan yang tidak terduga.','error');});
  async function handleLogin(e) {
    e.preventDefault();
    const username=$('loginUsername').value.trim(), password=$('loginPassword').value;
    $('loginError').hidden=true; $('loginSubmit').disabled=true; $('loginSubmit').innerHTML='<span class="spinner"></span> Memverifikasi…';
    try {
      const result=await api('login',{username,password},'POST',{timeout:20000,ttl:0,force:true});
      if(!result || !result.token)throw new Error('Backend tidak mengembalikan sesi login yang valid.');
      saveSession(result.token,result.username); $('loginPassword').value=''; state.cache.clear(); state.pending.clear(); showApp(); await init();
    } catch(err) { clearSession(); showLogin(err.message || 'Login gagal. Periksa username dan password.'); }
    finally { $('loginSubmit').disabled=false; $('loginSubmit').innerHTML='<i class="fa-solid fa-right-to-bracket"></i> Masuk'; }
  }
  async function logout() {
    const token=sessionToken();
    try { if(token) await api('logout',{},'POST',{timeout:10000,ttl:0,force:true}); } catch (_) {}
    clearSession(); state.cache.clear(); state.pending.clear(); state.periods=[]; state.kpi=[]; state.dashboard=null; state.rbb=null; state.renbis=[]; state.xray=[]; state.movers=null; state.trends=null; state.costs=null; state.manual=[]; state.database=[]; state.targets={}; state.actions=[]; showLogin(''); $('loginPassword').value=''; $('loginUsername').focus();
  }
  function boot() {
    // Defensif terhadap index.html dan app.js yang berasal dari versi berbeda.
    const loginForm = $('loginForm');
    const loginScreen = $('loginScreen');
    const loginUsername = $('loginUsername');
    const loginPassword = $('loginPassword');
    if (!loginForm || !loginScreen || !loginUsername || !loginPassword) {
      console.error(
        'PRIME Ledger: struktur halaman login tidak cocok dengan app.js. ' +
        'Pastikan index.html dan app.js berasal dari rilis yang sama, lalu deploy ulang dan bersihkan cache browser/CDN.',
        { loginForm: !!loginForm, loginScreen: !!loginScreen, loginUsername: !!loginUsername, loginPassword: !!loginPassword }
      );
      if (loginScreen) {
        loginScreen.hidden = false;
        const message = document.createElement('p');
        message.className = 'login-error';
        message.setAttribute('role', 'alert');
        message.textContent = 'Versi halaman tidak sinkron. Muat ulang aplikasi atau hubungi administrator.';
        loginScreen.querySelector('.login-card')?.appendChild(message);
      }
      return;
    }

    loginForm.addEventListener('submit', handleLogin);
    $('togglePassword')?.addEventListener('click', () => {
      const input = $('loginPassword');
      const toggle = $('togglePassword');
      if (!input || !toggle) return;
      const show = input.type === 'password';
      input.type = show ? 'text' : 'password';
      toggle.setAttribute('aria-label', show ? 'Sembunyikan password' : 'Tampilkan password');
      toggle.innerHTML = show ? '<i class="fa-solid fa-eye-slash"></i>' : '<i class="fa-solid fa-eye"></i>';
    });
    $('logoutBtn')?.addEventListener('click', logout);
    if (sessionToken()) {
      showApp();
      init().catch(err => {
        clearSession();
        showLogin(err.message || 'Sesi berakhir. Silakan login kembali.');
      });
    } else {
      showLogin('');
    }
  }
  document.addEventListener('DOMContentLoaded',boot);
})();
